using Microsoft.Extensions.AI;
using System.ComponentModel;
using System.Text.Json;

// --- Tool Definitions ---

/// <summary>Tools the research agent can invoke during its investigation.</summary>
public static class ResearchTools
{
    private static readonly HttpClient Http = new();
    private static readonly List<string> Notes = [];

    [Description("Search the web for information on a query. Returns a list of result snippets.")]
    public static async Task<string> WebSearch([Description("The search query")] string query)
    {
        Console.WriteLine($"  🔍 Searching: \"{query}\"");

        // Uses DuckDuckGo Instant Answer API (no key required)
        var encoded = Uri.EscapeDataString(query);
        var url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_html=1&skip_disambig=1";

        try
        {
            var json = await Http.GetStringAsync(url);
            using var doc = JsonDocument.Parse(json);
            var root = doc.RootElement;

            var results = new List<string>();

            // Abstract/summary
            var abs = root.GetProperty("Abstract").GetString();
            if (!string.IsNullOrWhiteSpace(abs))
                results.Add($"Summary: {abs}");

            // Related topics
            if (root.TryGetProperty("RelatedTopics", out var topics))
            {
                foreach (var topic in topics.EnumerateArray().Take(5))
                {
                    var text = topic.TryGetProperty("Text", out var t) ? t.GetString() : null;
                    if (!string.IsNullOrWhiteSpace(text))
                        results.Add(text);
                }
            }

            return results.Count > 0
                ? string.Join("\n\n", results)
                : $"No detailed results found for \"{query}\". Try rephrasing the search.";
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}";
        }
    }

    [Description("Save a research note. Use this to record important findings as you discover them.")]
    public static string TakeNote([Description("The note content to save")] string note)
    {
        Notes.Add(note);
        Console.WriteLine($"  📝 Note #{Notes.Count} saved.");
        return $"Note #{Notes.Count} saved successfully.";
    }

    [Description("Retrieve all saved research notes.")]
    public static string GetNotes()
    {
        if (Notes.Count == 0)
            return "No notes saved yet.";

        return string.Join("\n---\n", Notes.Select((n, i) => $"Note #{i + 1}: {n}"));
    }

    public static void Clear() => Notes.Clear();
}

// --- Main Program ---

Console.WriteLine("╔══════════════════════════════════════╗");
Console.WriteLine("║    🔬 AI Research Agent (.NET 10)    ║");
Console.WriteLine("╠══════════════════════════════════════╣");
Console.WriteLine("║ The agent will search the web and    ║");
Console.WriteLine("║ take notes to research your topic.   ║");
Console.WriteLine("╚══════════════════════════════════════╝");
Console.WriteLine();

// Configure the chat client — set OPENAI_API_KEY and optionally MODEL_NAME
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY") ?? "your-api-key-here";
var modelName = Environment.GetEnvironmentVariable("MODEL_NAME") ?? "gpt-4o-mini";

IChatClient client = new ChatClientBuilder(
        new OpenAI.OpenAIClient(apiKey).GetChatClient(modelName).AsIChatClient())
    .UseFunctionInvocation()
    .Build();

var tools = new ChatOptions
{
    Tools =
    [
        AIFunctionFactory.Create(ResearchTools.WebSearch),
        AIFunctionFactory.Create(ResearchTools.TakeNote),
        AIFunctionFactory.Create(ResearchTools.GetNotes),
    ]
};

while (true)
{
    Console.Write("\n📌 Enter a research topic (or 'quit' to exit): ");
    var topic = Console.ReadLine()?.Trim();
    if (string.IsNullOrEmpty(topic) || topic.Equals("quit", StringComparison.OrdinalIgnoreCase))
        break;

    ResearchTools.Clear();
    Console.WriteLine($"\n🤖 Researching: \"{topic}\"...\n");

    var messages = new List<ChatMessage>
    {
        new(ChatRole.System, """
            You are a research agent. Your job is to thoroughly research a topic using the tools available.

            Strategy:
            1. Perform multiple web searches with different angles/queries to gather broad information.
            2. Take notes on key findings as you go.
            3. After gathering enough information, retrieve your notes and provide a well-structured summary.

            Always perform at least 2-3 searches before summarizing. Take notes after each search
            with the most important facts. End with a comprehensive summary.
            """),
        new(ChatRole.User, $"Please research the following topic and provide a detailed summary: {topic}")
    };

    try
    {
        var response = await client.GetResponseAsync(messages, tools);
        Console.WriteLine("\n════════════════════════════════════════");
        Console.WriteLine("📋 RESEARCH SUMMARY");
        Console.WriteLine("════════════════════════════════════════\n");
        Console.WriteLine(response.Text);
        Console.WriteLine("\n════════════════════════════════════════");
    }
    catch (Exception ex)
    {
        Console.WriteLine($"\n❌ Error: {ex.Message}");
        if (apiKey == "your-api-key-here")
            Console.WriteLine("💡 Set the OPENAI_API_KEY environment variable to use this agent.");
    }
}

