using System.ComponentModel;
using System.Text.Json;

/// <summary>Tools the research agent can invoke during its investigation.</summary>
public static class ResearchTools
{
    private static readonly HttpClient Http = new();
    private static readonly List<string> Notes = [];

    [Description("Search the web for information on a query. Returns a list of result snippets.")]
    public static async Task<string> WebSearch([Description("The search query")] string query)
    {
        Console.WriteLine($"  🔍 Searching: \"{query}\"");

        // Uses DuckDuckGo Instant Answer API (no key required)
        var encoded = Uri.EscapeDataString(query);
        var url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_html=1&skip_disambig=1";

        try
        {
            var json = await Http.GetStringAsync(url);
            using var doc = JsonDocument.Parse(json);
            var root = doc.RootElement;

            var results = new List<string>();

            // Abstract/summary
            var abs = root.GetProperty("Abstract").GetString();
            if (!string.IsNullOrWhiteSpace(abs))
                results.Add($"Summary: {abs}");

            // Related topics
            if (root.TryGetProperty("RelatedTopics", out var topics))
            {
                foreach (var topic in topics.EnumerateArray().Take(5))
                {
                    var text = topic.TryGetProperty("Text", out var t) ? t.GetString() : null;
                    if (!string.IsNullOrWhiteSpace(text))
                        results.Add(text);
                }
            }

            return results.Count > 0
                ? string.Join("\n\n", results)
                : $"No detailed results found for \"{query}\". Try rephrasing the search.";
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}";
        }
    }

    [Description("Save a research note. Use this to record important findings as you discover them.")]
    public static string TakeNote([Description("The note content to save")] string note)
    {
        Notes.Add(note);
        Console.WriteLine($"  📝 Note #{Notes.Count} saved.");
        return $"Note #{Notes.Count} saved successfully.";
    }

    [Description("Retrieve all saved research notes.")]
    public static string GetNotes()
    {
        if (Notes.Count == 0)
            return "No notes saved yet.";

        return string.Join("\n---\n", Notes.Select((n, i) => $"Note #{i + 1}: {n}"));
    }

    public static void Clear() => Notes.Clear();
}

