using Microsoft.Extensions.AI;

Console.WriteLine("╔══════════════════════════════════════╗");
Console.WriteLine("║    🔬 AI Research Agent (.NET 10)    ║");
Console.WriteLine("╠══════════════════════════════════════╣");
Console.WriteLine("║ The agent will search the web and    ║");
Console.WriteLine("║ take notes to research your topic.   ║");
Console.WriteLine("╚══════════════════════════════════════╝");
Console.WriteLine();

// Configure the chat client — set OPENAI_API_KEY and optionally MODEL_NAME
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY") ?? "your-api-key-here";
var modelName = Environment.GetEnvironmentVariable("MODEL_NAME") ?? "gpt-4o-mini";

IChatClient client = new ChatClientBuilder(
        new OpenAI.OpenAIClient(apiKey).GetChatClient(modelName).AsIChatClient())
    .UseFunctionInvocation()
    .Build();

var tools = new ChatOptions
{
    Tools =
    [
        AIFunctionFactory.Create(ResearchTools.WebSearch),
        AIFunctionFactory.Create(ResearchTools.TakeNote),
        AIFunctionFactory.Create(ResearchTools.GetNotes),
    ]
};

while (true)
{
    Console.Write("\n📌 Enter a research topic (or 'quit' to exit): ");
    var topic = Console.ReadLine()?.Trim();
    if (string.IsNullOrEmpty(topic) || topic.Equals("quit", StringComparison.OrdinalIgnoreCase))
        break;

    ResearchTools.Clear();
    Console.WriteLine($"\n🤖 Researching: \"{topic}\"...\n");

    var messages = new List<ChatMessage>
    {
        new(ChatRole.System, """
            You are a research agent. Your job is to thoroughly research a topic using the tools available.

            Strategy:
            1. Perform multiple web searches with different angles/queries to gather broad information.
            2. Take notes on key findings as you go.
            3. After gathering enough information, retrieve your notes and provide a well-structured summary.

            Always perform at least 2-3 searches before summarizing. Take notes after each search
            with the most important facts. End with a comprehensive summary.
            """),
        new(ChatRole.User, $"Please research the following topic and provide a detailed summary: {topic}")
    };

    try
    {
        var response = await client.GetResponseAsync(messages, tools);
        Console.WriteLine("\n════════════════════════════════════════");
        Console.WriteLine("📋 RESEARCH SUMMARY");
        Console.WriteLine("════════════════════════════════════════\n");
        Console.WriteLine(response.Text);
        Console.WriteLine("\n════════════════════════════════════════");
    }
    catch (Exception ex)
    {
        Console.WriteLine($"\n❌ Error: {ex.Message}");
        if (apiKey == "your-api-key-here")
            Console.WriteLine("💡 Set the OPENAI_API_KEY environment variable to use this agent.");
    }
}

